class Solution {
public:
    bool canRemoveAll(vector<int>& types, vector<int>& colors, vector<int>& groupSize) {
        struct Run {
            int type;
            int color;
            int cnt;
        };
        vector<Run> st;
        st.reserve(types.size());

        for (size_t i = 0; i < types.size(); ++i) {
            int t = types[i];
            int c = colors[i];
            if (!st.empty() && st.back().type == t && st.back().color == c) {
                ++st.back().cnt;
            } else {
                st.push_back({t, c, 1});
            }
            if (st.back().cnt == groupSize[t]) {
                st.pop_back();          // remove the whole run
            }
        }
        return st.empty();
    }
};
